import pickle
import time

class SessionCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.max_size = max_size
        self.access_times = {}

    def set(self, session_id, session_obj):
        """Store a session object in cache using pickle for speed."""
        if len(self.cache) >= self.max_size:
            # Evict least recently used
            lru_id = min(self.access_times, key=self.access_times.get)
            del self.cache[lru_id]
            del self.access_times[lru_id]

        self.cache[session_id] = pickle.dumps(session_obj)
        self.access_times[session_id] = time.time()

    def get(self, session_id):
        """Retrieve and deserialize a session object."""
        if session_id in self.cache:
            self.access_times[session_id] = time.time()
            return pickle.loads(self.cache[session_id])
        return None

    def delete(self, session_id):
        if session_id in self.cache:
            del self.cache[session_id]
            del self.access_times[session_id]
